import express from 'express'
const app = express()

const fakeDb = { find: async (id) => { if (id === '0') throw new Error('DB down'); return null } }

// Express 5: just throw / reject
app.get('/v5/users/:id', async (req, res) => {
  const user = await fakeDb.find(req.params.id)
  if (!user) throw Object.assign(new Error('User not found'), { status: 404 })
  res.json(user)
})

// Express 4 compatible wrapper (also fine in 5)
const asyncHandler = (fn) => (req, res, next) => Promise.resolve(fn(req, res, next)).catch(next)
app.get('/v4/users/:id', asyncHandler(async (req, res) => {
  const user = await fakeDb.find(req.params.id)
  if (!user) throw Object.assign(new Error('User not found'), { status: 404 })
  res.json(user)
}))

app.use((err, req, res, next) => {
  res.status(err.status || 500).json({ error: err.message })
})

app.listen(3000)

