import express from 'express'
const app = express()
app.use(express.json())

function validateUser({ name, email, age }) {
  const errors = []
  if (!name || name.length < 2) errors.push({ field: 'name', message: 'Name must have 2+ characters' })
  if (!/^\S+@\S+\.\S+$/.test(email ?? '')) errors.push({ field: 'email', message: 'Invalid email' })
  if (!Number.isInteger(age) || age < 0) errors.push({ field: 'age', message: 'Age must be a positive integer' })
  return errors
}

app.post('/users', (req, res) => {
  const errors = validateUser(req.body ?? {})
  if (errors.length) {
    return res.status(422).json({ status: 'fail', message: 'Validation failed', errors })
  }
  res.status(201).json({ status: 'success', data: req.body })
})

// route not found
app.use((req, res) => {
  res.status(404).json({ status: 'fail', message: `Cannot ${req.method} ${req.originalUrl}` })
})

app.listen(3000)

import express from 'express'
import mongoose from 'mongoose'

const app = express()
app.get('/health', (req, res) => res.json({ status: 'ok' }))

await mongoose.connect(process.env.MONGO_URI)
const server = app.listen(process.env.PORT || 3000, () => console.log('listening'))

let shuttingDown = false
async function shutdown(signal, code = 0) {
  if (shuttingDown) return
  shuttingDown = true
  console.log(`${signal} received: closing server`)

  const force = setTimeout(() => {
    console.error('Forced exit after timeout')
    process.exit(1)
  }, 10_000)
  force.unref()

  server.close(async () => {          // waits for in-flight requests
    await mongoose.connection.close()
    console.log('Closed cleanly')
    process.exit(code)
  })
  server.closeIdleConnections()
}

process.on('SIGTERM', () => shutdown('SIGTERM'))
process.on('SIGINT', () => shutdown('SIGINT'))
process.on('unhandledRejection', (reason) => {
  console.error('Unhandled rejection:', reason)
  shutdown('unhandledRejection', 1)
})
process.on('uncaughtException', (err) => {
  console.error('Uncaught exception:', err)
  shutdown('uncaughtException', 1)
})
